import React, { useState } from 'react';
import './signup.css';

const API_BASE_URL = "http://localhost:8081/api";

function SignupForm() {
  const [formData, setFormData] = useState({ username: '', email: '', password: '' });
  const [otp, setOtp] = useState('');
  const [step, setStep] = useState('signup'); // signup | otp | done
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setMessage('');
    setLoading(true);
    try {
      const userPayload = {
        username: formData.username,
        email: formData.email,
        passwordHash: formData.password,
        firstName: "-",
        lastName: "-",
        phone: "-",
        role: "DEFAULT_USER",
      };
      const res = await fetch(`${API_BASE_URL}/users`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(userPayload),
      });
      if (!res.ok) throw new Error(await res.text());
      setStep('otp');
      setMessage('✅ OTP sent to your email. Please verify.');
    } catch (err) {
      setError(err.message || 'Signup failed');
    } finally {
      setLoading(false);
    }
  };

  const handleOtpSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setMessage('');
    setLoading(true);
    try {
      const res = await fetch(`${API_BASE_URL}/users/verify-otp`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: formData.email, otp }),
      });
      if (!res.ok) throw new Error(await res.text());

      // Signup success email
      await fetch(`${API_BASE_URL}/send-signup-success`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: formData.email, username: formData.username }),
      });

      setStep('done');
      setMessage('🎉 Signup successful! Your email is verified.');
    } catch (err) {
      setError(err.message || 'Invalid OTP');
    } finally {
      setLoading(false);
    }
  };

  const handleResendOtp = async () => {
    setError('');
    setMessage('');
    try {
      await handleSubmit({ preventDefault: () => {} }); // re-trigger signup
      setMessage('🔄 OTP resent to your email.');
    } catch (err) {
      setError(err.message || 'Failed to resend OTP');
    }
  };

  return (
    <div className="signup-container">
      <div className="signup-box">
        {step === 'signup' && (
          <>
            <h2>Sign Up</h2>
            <form onSubmit={handleSubmit}>
              <input type="text" name="username" placeholder="Username" value={formData.username} onChange={handleChange} required />
              <input type="email" name="email" placeholder="Email" value={formData.email} onChange={handleChange} required />
              <input type="password" name="password" placeholder="Password" value={formData.password} onChange={handleChange} required />
              <button type="submit" disabled={loading}>{loading ? 'Signing Up...' : 'Sign Up'}</button>
            </form>
          </>
        )}

        {step === 'otp' && (
          <>
            <h2>Verify OTP</h2>
            <form onSubmit={handleOtpSubmit}>
              <input type="text" placeholder="Enter OTP" value={otp} onChange={(e) => setOtp(e.target.value)} required />
              <button type="submit" disabled={loading}>{loading ? 'Verifying...' : 'Verify'}</button>
            </form>
            <p style={{ marginTop: '10px' }}>
              Didn’t get OTP?{' '}
              <button type="button" onClick={handleResendOtp} style={{ color: 'blue', background: 'none', border: 'none', cursor: 'pointer' }}>
                Resend
              </button>
            </p>
          </>
        )}

        {step === 'done' && (
          <div style={{ textAlign: 'center' }}>
            <h2>✅ Signup Complete</h2>
            <p>Your account has been verified successfully.</p>
            <h3 style={{ marginTop: '10px', color: 'green' }}>🎉 Signup successful! Your email is verified.</h3>
          </div>
        )}

        {step !== 'done' && message && <p style={{ color: 'green' }}>{message}</p>}
        {error && <p style={{ color: 'red' }}>{error}</p>}
      </div>
    </div>
  );
}

export default SignupForm;
